-- wave-rewrite-now-2026-10-08: read-only preflight of paste-2026-10-08.sql. Expect 0 rows; a row names a statement whose
-- guard does not match exactly one card, or whose new text does not decode to the intended bytes.
select t.n, t.slug, t.field, t.rows_matched, t.text_ok
from (values
  (1, 'amavi-canggu-bali', 'why_its_here', (select count(*)::int from venues where slug = 'amavi-canggu-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '50cd48dd5383873cb9a32ee010c95f4f'), md5('The menu at AMAVI goes from nasi goreng and sate ayam to Angus ribeye and pizza. It''s a restaurant and bar lounge on Jl. Pantai Berawa, run on a Mediterranean concept, with a pool and rice field views.') = '7f5a3bfda76d8776fd9a3b474d394b2e'),
  (2, 'cafe-coach', 'why_its_here', (select count(*)::int from venues where slug = 'cafe-coach' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cfe84dc71a22ca59e87ad96ce3eda104'), md5(U&'On Jl. Nelayan in Canggu, Cafe Coach is an all-day caf\00E9 that doubles as a wellness-coaching space and hosts workshops. The large menu runs from breakfast to dinner (benedicts, poke bowls, burgers), with coffee and cocktails.') = 'f685718444da7aaac96d12e6fdd4176f'),
  (3, 'cafe-coach', 'best_for', (select count(*)::int from venues where slug = 'cafe-coach' and status = 'active' and publication_status = 'published' and md5(best_for) = '8d3aff3a52385ac2968f05840848df0b'), md5('Breakfast, or dinner that runs into cocktails') = 'd5ce955599499215a341fed75f004c32'),
  (4, 'mavammy', 'why_its_here', (select count(*)::int from venues where slug = 'mavammy' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fdf285168b51f8c2b14c9dafbed58455'), md5(U&'Mavammy''s dessert counter is built on Belgian chocolate, and breakfast runs all day at this caf\00E9 and patisserie on Jl. Pantai Batu Bolong. The cakes include carrot cake with mango and passion fruit, and a Lotus cheesecake. The wifi is strong and there''s air conditioning.') = 'aa2cd5cdedc8715ac11c7ed6a7fc6ed0'),
  (5, 'porch', 'why_its_here', (select count(*)::int from venues where slug = 'porch' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'b8d1ffe728d5732e450a536f498291d8'), md5('Thirteen kinds of cheesecake are the reason to come to Porch, a coffee shop on Jl. Raya Semat.') = 'd258f4330152e6bbc5b1352c2c60a552'),
  (6, 'pranava-yoga', 'why_its_here', (select count(*)::int from venues where slug = 'pranava-yoga' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '616eb34f2ed717b5db20fcb3e9d6c49b'), md5('Vicki and Yuni opened Pranava Yoga in April 2016, at the Matrabali guesthouse on Jl. Pantai Berawa. Rates sit below the premium Canggu studios so local residents can practise too, and classes suit every level.') = '4625f88c88a8fdbfd443adef6cbeacfa'),
  (7, 'mamu-ubud-cafe-shisha-hookah', 'why_its_here', (select count(*)::int from venues where slug = 'mamu-ubud-cafe-shisha-hookah' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1f0d9b93451d46fa908755cf1a4805d8'), md5(U&'Darkside, Musthave and Duft are on the shisha list at MAMU, a caf\00E9 and shisha lounge on Jl. Made Lebah in Mas. The food is bowls, roasted vegetables, warm dips and shawarma, and there is an air-conditioned lounge as well as a garden terrace.') = 'cb48c0302a9e71dc8b269f7d1ed94c86'),
  (8, 'dewas-landing-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'dewas-landing-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd1f1a6b67218e41ca16454b40fad5aab'), md5('Dewas Landing Cafe, on Jl. Raya Uluwatu in Pecatu, is a local gathering point that runs football watch parties.') = '5eb5e9f15acb84ca4d78df17cccfe70e'),
  (9, 'humans-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'humans-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'd83c14ea2575b8206e07f40d73bfdc7f'), md5('HUMANS CAFE, on Jl. Bali Cliff in Ungasan, serves Asian, Indonesian and European plates with specialty coffee. There''s a playground for children.') = '5418c57a43dda63f02a510ee166e3dc5'),
  (10, 'lemanja-uluwatu', 'why_its_here', (select count(*)::int from venues where slug = 'lemanja-uluwatu' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '067a541ccb10dbfd44fca01b15cd17ff'), md5(U&'Breakfast at Lemanj\00E1 Uluwatu starts at 07:30. It''s a caf\00E9, bar and coworking space with a pool on Jl. Labuansait. Plates start at 20,000 IDR, and the menu runs to pan-grilled prawns, tuna tataki, vegan quesadillas and plant-based pizza, with pastries alongside the cocktails.') = 'aefe4776afe6d8fc1eab214088937596'),
  (11, 'made-s-bakery-cafe-playground', 'why_its_here', (select count(*)::int from venues where slug = 'made-s-bakery-cafe-playground' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5e9ef531001fa1271d7c0c3d55903a3a'), md5(U&'Made\2019s Bakery Cafe Playground grew out of a small warung and has been a bakery and caf\00E9 on Jl. Dharmawangsa in Ungasan since 2025. Expect pastries, desserts and coffee, breakfast all day in large portions, and a playground that is free to use.') = '307eb62569708f96c27d7dbb8cff2245'),
  (12, 'ula-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'ula-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '78ab2473ceacbeff24c6bb5da311e92b'), md5('Chef Mags builds the menu from scratch at Ula Cafe on Jl. Pantai Balangan and keeps separate breakfast and mains lists. There are woven textures, ocean air and vinyl in the background, plus wifi and power outlets throughout.') = '42e1693929d2cbe8d0f56f5a7cab09e8'),
  (13, 'uluwatu-collective', 'why_its_here', (select count(*)::int from venues where slug = 'uluwatu-collective' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cefc1ce4126de75fff703e5daa74a8b5'), md5('At Uluwatu Collective, CrossFit, Metcon, HIIT, weightlifting, functional training and yoga run as group classes. The gym is high-ceilinged and open-air, above Pepito Express on Jl. Raya Uluwatu. Access is sold daily, weekly, monthly or yearly, and a month is 1,450,000 IDR.') = '4bb1d36c6f1b2d999ac5695fb58e9111'),
  (14, 'de-maison-bali-restaurant-and-bar', 'why_its_here', (select count(*)::int from venues where slug = 'de-maison-bali-restaurant-and-bar' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c417ee6f620e9bd4740f213f761b4446'), md5('De Maison Bali Restaurant & Bar, in Renon, Denpasar, is a coffee shop on Jl. Tukad Badung.') = 'bbf44041c2fdd3f3f0634322b263e63d'),
  (15, 'manga-madu', 'best_for', (select count(*)::int from venues where slug = 'manga-madu' and status = 'active' and publication_status = 'published' and md5(best_for) = '07e031152c190c3e1eb2d5b43a850fa7'), md5('A budget meal of classic Indonesian comfort food close to central Ubud') = '330d67255f856f7c6548c7e2b85fd3fe'),
  (16, 'manga-madu', 'not_for', (select count(*)::int from venues where slug = 'manga-madu' and status = 'active' and publication_status = 'published' and md5(not_for) = '31d4a9892e1e389d4d43a2a8315e0512'), md5('A fine-dining atmosphere or an extensive wine list: this is a budget warung') = '99c41b7e415dc118a6f4eba705426a4c')
) as t(n, slug, field, rows_matched, text_ok)
where t.rows_matched <> 1 or not t.text_ok
order by t.n;
